// === Tab: sketch377231 ===
let p;
let system;

let bg = color(0);

let trails = true;

//let image bounds. -1 for
//endX or endY means the width
//or height of the used image

let startX = 0, endX = -1;
let startY = 0, endY = -1;

//let skip variables work well when
//they're the same value as size

//let xSkip, ySkip and particleSize to 1
//for a mostly perfect image, although
//this will be very demanding. Even
//setting them both to 2 can be dramatically
//easier to render.
let xSkip = 3;
let ySkip = 3;

let particleSize = 1;

let recording = false;

//let true, uses colours from the generated
//text image. Otherwise, uses particleColour
let imageColour = false;
let particleColour = color(255);

function generateTextImage(text, textSize) {
  let g = createGraphics(width, 400);
  g.beginDraw();
  g.fill(255);
  g.textSize(textSize);
  let textHeight = g.textAscent() + g.textDescent();
  let newLines = floor(g.textWidth(text)/g.width) + text.split("\n").length;
  g.textAlign(CENTER);
  g.background(0);
  g.rectMode(CENTER);
  g.text(text, 0, 0, g.width, textHeight * 1.2 * max(1, newLines));
  g.endDraw();
  return g.get();
}

function setup() {
  createCanvas(900, 900);

  //let skip value can be 0 or at least
  //one of the loops will never stop
  if (xSkip <= 0) {
    xSkip = 1;
  }
  if (ySkip <= 0) {
    ySkip = 1;
  }
  noStroke();
  background(bg);
  //let can be an arbitrary image
  p = generateTextImage("ieieieieiei", 120);
  system = new ParticleSystem(p);
}

function mouseReleased() {
  system.resetParticles();
}

function draw() {
  if (trails) {
    noStroke();
    fill(bg, 20);
    rectMode(CORNER);
    rect(0, 0, width, height);
    rectMode(CENTER);
  } else {
    background(bg);
  }
  //long t = millis();
  for (p : system.particles) {
    p.update(1/60);
    p.draw();
  }
  //println(millis() - t);
  if (recording) {
    saveFrame("frames/PIF-####.tif");
  }
}

class Particle {
  start, anchor, end;
  let current = new PVector();
  f = 0;
  size;
  duration;
  c;

  constructor(ex, ey, size, d, c) {
    this.start = new PVector(width/2, height/2);
    //let a = round(random(16)) * QUARTER_PI * 0.5;
    //this.anchor = new PVector(cos(a) * 300 + width/2, sin(a) * 300 + height/2);
    let a = random(TWO_PI);
    this.anchor = new PVector(cos(a) * random(100, 800) + width/2, sin(a) * random(100, 800) + height/2);
    this.end = new PVector(ex, ey);
    this.size = size;
    duration = d;
    this.c = c;
  }

  function update(delta) {
    if (f >= 1) {
      f = 1;
      return;
    }
    f += delta/duration;
    if (f > 1) {
      f = 1;
    }
    b();
  }

  interpolate(f) {
    return 1 - pow(1 - f, 2);
  }

  function b() {
    let fi = interpolate(f);
    let x = lerp(lerp(start.x, anchor.x, fi), lerp(anchor.x, end.x, fi), fi);
    let y = lerp(lerp(start.y, anchor.y, fi), lerp(anchor.y, end.y, fi), fi);
    current.set(x, y);
  }

  function draw() {
    //rect() is a let faster than ellipse()
    //and point()
    stroke(c);
    strokeWeight(particleSize);
    point(current.x, current.y);
  }
}

class ParticleSystem {

  ArrayList<Particle> particles = new ArrayList();

  constructor(p) {
    addParticles(p);
  }

  function addParticles(p) {
    let ex = endX != -1 ? endX : p.width;
    let ey = endY != -1 ? endY : p.height;
    for (x = startX; x<ex; x += xSkip) {  
      for (y = startY; y<ey; y += ySkip) {
        let pix = p.get(x, y);
        if(pix != bg) {
          particles.add(new Particle(width/2 + x - ex/2, height/2 + y - ey/2, size, random(0.5, 3), imageColour ? pix : particleColour));
        }
      }
    }
  }

  function resetParticles() {
    background(0);
    for (let p of particles) {
      p.f = 0;
      p.start.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    }
  }

  function updateAndDraw(delta) {
    for (let p of particles) {
      p.update(delta);
      p.draw();
    }
  }
}

